print(f"Total samples: {len(samples)}")

# Test each sample individually
for idx, pair in enumerate(samples):
    raw = pair["raw_asr"]
    ref = pair["refined_text"]
    words = len(ref.split())
    v_ok, v_msg = validate_pair(pair)
    c_res, c_msg = clean_sample(raw, ref)
    tier = "Short" if words < 25 else ("Medium" if words <= 90 else "Long")
    print(f"Sample {idx+1:02d} [{tier}, {words:3d}w]: validate_pair={v_ok} ({v_msg}), clean_sample={c_msg}")
    if not v_ok or c_res is None:
        print(f"FAILED on sample {idx+1}!")
        sys.exit(1)

# Test batch validation
b_ok, b_msg, tier_counts = validate_batch(samples, min_short=4, min_medium=6, min_long=10)
print(f"\nBatch validation: {b_ok} ({b_msg}), tier_counts={tier_counts}")
if not b_ok:
    print("FAILED batch validation!")
    sys.exit(1)

